begin;
create extension if not exists pgcrypto;
create table if not exists public.members(user_id uuid primary key references auth.users(id) on delete cascade, role text not null default 'admin' check(role in ('admin','staff')), created_at timestamptz default now());
create table if not exists public.settings(id text primary key default 'business' check(id='business'), automation_enabled boolean not null default false, questions jsonb not null default '[]', faqs jsonb not null default '[]', rules text not null default '', rule_version integer not null default 1, followup_text text not null default 'Hi! Would you like to continue your application? I can help with the remaining questions.', followup_media_url text default '', followup_media_type text default 'image', min_gap_hours numeric not null default 2 check(min_gap_hours>=0.25), quiet_start integer not null default 21 check(quiet_start between 0 and 23), quiet_end integer not null default 8 check(quiet_end between 0 and 23), confidence_threshold numeric not null default 0.85 check(confidence_threshold between 0.5 and 1), completion_text text not null default 'Thank you! Your details are ready for our team to review.', utility_templates jsonb not null default '[]');
insert into public.settings(id) values('business') on conflict do nothing;
create table if not exists public.pages(id text primary key, name text not null, token_encrypted text not null, connected boolean not null default true, capabilities jsonb not null default '{}', updated_at timestamptz default now());
create table if not exists public.contacts(id uuid primary key default gen_random_uuid(),page_id text not null references public.pages(id),psid text not null,name text not null default 'Messenger contact',status text not null default 'new' check(status in ('new','incomplete','review','qualified','unqualified')), opted_out boolean not null default false,human_takeover boolean not null default false,first_inquiry_at timestamptz not null default now(),last_inbound_at timestamptz,last_outbound_at timestamptz,timezone text not null default 'Asia/Manila',notes text not null default '',details jsonb not null default '{}',answers jsonb not null default '{}',tags text[] not null default '{}',ad_id text,awaiting_question text,recommendation jsonb,created_at timestamptz default now(),unique(page_id,psid));
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),contact_id uuid not null references public.contacts(id) on delete cascade,external_id text unique,direction text not null check(direction in ('in','out')),text text not null default '',media jsonb not null default '[]',status text not null default 'received',sent_at timestamptz not null default now());
create index if not exists messages_contact_time on public.messages(contact_id,sent_at);
create table if not exists public.webhook_events(id text primary key,payload jsonb not null,created_at timestamptz default now());
create table if not exists public.jobs(id uuid primary key default gen_random_uuid(),action_key text unique not null,kind text not null,contact_id uuid references public.contacts(id) on delete cascade,payload jsonb not null default '{}',due_at timestamptz not null default now(),status text not null default 'pending' check(status in ('pending','running','done','blocked','failed','uncertain','canceled')),attempts integer not null default 0,last_error text,locked_at timestamptz,created_at timestamptz default now());
create index if not exists jobs_due on public.jobs(status,due_at);
create table if not exists public.outbound_attempts(action_key text primary key,contact_id uuid not null references public.contacts(id),message_id text,status text not null default 'sending',reason text,created_at timestamptz default now());
create table if not exists public.meetings(id uuid primary key default gen_random_uuid(),title text not null,starts_at timestamptz not null,timezone text not null default 'Asia/Manila',url text not null,capacity integer not null default 100 check(capacity>0),notes text not null default '',reminder_minutes integer[] not null default '{1440,60}',reminder_text text not null default 'Reminder: {{title}} starts at {{date}}. {{notes}}',canceled boolean not null default false,created_at timestamptz default now());
create table if not exists public.invitations(id uuid primary key default gen_random_uuid(),meeting_id uuid not null references public.meetings(id),contact_id uuid not null references public.contacts(id),rsvp text not null default 'invited' check(rsvp in ('invited','yes','no')),clicked_at timestamptz,attended boolean,unique(meeting_id,contact_id));
create table if not exists public.tracked_links(id uuid primary key default gen_random_uuid(),contact_id uuid not null references public.contacts(id),meeting_id uuid references public.meetings(id),url text not null,clicks integer not null default 0,last_clicked_at timestamptz);
create table if not exists public.campaigns(id uuid primary key default gen_random_uuid(),name text not null,content jsonb not null,filter jsonb not null default '{}',created_at timestamptz default now());
create table if not exists public.ad_daily(id text primary key,ad_id text not null,date date not null,ad_name text,campaign_name text,spend numeric not null default 0,currency text,unique(ad_id,date));
create table if not exists public.ad_accounts(id text primary key,name text not null,token_encrypted text not null,updated_at timestamptz default now());
create table if not exists public.audit_log(id uuid primary key default gen_random_uuid(),action text not null,actor text not null default 'system',details jsonb,created_at timestamptz default now());
create table if not exists public.contact_locks(contact_id uuid primary key,expires_at timestamptz not null);
create or replace function public.claim_jobs(batch_size integer default 10) returns setof public.jobs language plpgsql security definer set search_path=public as $$ begin
  update jobs set status=case when kind='webhook' then 'pending' else 'uncertain' end,last_error='Worker lease expired; check outcome before retrying' where status='running' and locked_at<now()-interval '5 minutes';
  return query update jobs set status='running',locked_at=now(),attempts=attempts+1 where id in(select id from jobs where status='pending' and due_at<=now() order by due_at for update skip locked limit least(batch_size,20)) returning *;
end $$;
create or replace function public.acquire_contact_lock(cid uuid) returns boolean language plpgsql security definer set search_path=public as $$ declare n integer; begin insert into contact_locks(contact_id,expires_at) values(cid,now()+interval '2 minutes') on conflict(contact_id) do update set expires_at=excluded.expires_at where contact_locks.expires_at<now(); get diagnostics n=row_count; return n>0; end $$;
create or replace function public.release_contact_lock(cid uuid) returns void language sql security definer set search_path=public as $$ delete from contact_locks where contact_id=cid $$;
create or replace function public.rsvp_meeting(mid uuid,cid uuid,answer text) returns text language plpgsql security definer set search_path=public as $$ declare m meetings; current_reply text; begin
 select * into m from meetings where id=mid for update;
 if not found or m.canceled or m.starts_at<now() then return 'unavailable'; end if;
 select rsvp into current_reply from invitations where meeting_id=mid and contact_id=cid;
 if not found then return 'not_invited'; end if;
 if answer not in ('yes','no') then return 'invalid'; end if;
 if answer='yes' and current_reply<>'yes' and (select count(*) from invitations where meeting_id=mid and rsvp='yes')>=m.capacity then return 'full'; end if;
 update invitations set rsvp=answer where meeting_id=mid and contact_id=cid;
 return answer;
end $$;
create or replace function public.track_click(lid uuid) returns text language plpgsql security definer set search_path=public as $$ declare l tracked_links; begin update tracked_links set clicks=clicks+1,last_clicked_at=now() where id=lid returning * into l; if not found then return null; end if; update invitations set clicked_at=now() where contact_id=l.contact_id and meeting_id=l.meeting_id; return l.url; end $$;
do $$ declare t text; begin foreach t in array array['members','settings','pages','contacts','messages','webhook_events','jobs','outbound_attempts','meetings','invitations','tracked_links','campaigns','ad_daily','ad_accounts','audit_log','contact_locks'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
-- Application access is through authenticated server handlers. Browser/anonymous clients get no table access.
revoke all on public.members,public.settings,public.pages,public.contacts,public.messages,public.webhook_events,public.jobs,public.outbound_attempts,public.meetings,public.invitations,public.tracked_links,public.campaigns,public.ad_daily,public.ad_accounts,public.audit_log,public.contact_locks from anon,authenticated;
revoke execute on function public.claim_jobs(integer), public.acquire_contact_lock(uuid), public.release_contact_lock(uuid), public.rsvp_meeting(uuid,uuid,text), public.track_click(uuid) from public,anon,authenticated;
grant execute on function public.claim_jobs(integer), public.acquire_contact_lock(uuid), public.release_contact_lock(uuid), public.rsvp_meeting(uuid,uuid,text), public.track_click(uuid) to service_role;
commit;
